<section><div class="d-flex justify-content-between align-items-center mb-3"><h1 class="h3">我的云主机</h1><a class="btn btn-primary" href="<?= h(url_to('index/shop/index')) ?>">购买主机</a></div><?php if (!$services): ?><div class="empty">暂无云主机</div><?php else: ?><div class="row g-3"><?php foreach ($services as $service): ?><div class="col-md-6"><div class="card p-4 h-100"><div class="d-flex justify-content-between"><h2 class="h5"><?= h($service['hostname'] ?: '未命名主机') ?></h2><?= status_badge($service['status'], 'service') ?></div><div class="small text-muted mb-3"><?= h($service['ip'] ?: 'IP 分配中') ?> · 到期 <?= h($service['due_time'] ? date('Y-m-d', $service['due_time']) : '—') ?></div><a class="btn btn-outline-primary" href="<?= h(url_to('index/host/detail', ['id' => $service['id']])) ?>">管理主机</a></div></div><?php endforeach; ?></div><?php endif; ?></section>
